select '43b567ca-feab-5b36-a838-562e4ae33ba3', e.id, 'MA', (select id from public.content_components where code = 'MA.CAT.ALG'), 'qa_passed', 'continuous', '{"title":"Descuentos encadenados","text":"Un almacén anuncia: «20 % de descuento en toda la tienda y, en la caja, un 10 % adicional sobre el precio ya rebajado». Un par de tenis cuesta $100.000 antes de los descuentos.","svg":null,"table":null}'::jsonb, 'Un cliente dice que los dos descuentos equivalen a un descuento único del 30 %. ¿Es correcto su razonamiento?', '[{"label":"A","text":"Sí, porque el orden de los descuentos no importa.","is_correct":false,"distractor_type":"Da una razón que no justifica el 30 %.","explanation_feedback":"Incorrecta. El orden no importa, pero el total sigue siendo 28 %."},{"label":"B","text":"No: equivalen a un descuento del 28 %.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. 0,8 × 0,9 = 0,72: se paga el 72 %, es decir, un descuento del 28 %."},{"label":"C","text":"Sí, porque 20 % + 10 % = 30 %.","is_correct":false,"distractor_type":"Suma porcentajes que se aplican sobre bases distintas.","explanation_feedback":"Incorrecta. Los porcentajes sucesivos se multiplican, no se suman."},{"label":"D","text":"No, equivalen a un descuento del 32 %.","is_correct":false,"distractor_type":"Calcula mal el efecto combinado.","explanation_feedback":"Incorrecta. El efecto es 28 %, menor que 30 %."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
