select '8327edf3-fcc5-58c0-8525-acc83b4435cd', e.id, 'MA', (select id from public.content_components where code = 'MA.CAT.GEO'), 'qa_passed', 'continuous', '{"title":"Mapa a escala","text":"Un mapa turístico tiene escala 1 : 50.000, es decir, 1 cm en el mapa representa 50.000 cm en la realidad.","svg":null,"table":null}'::jsonb, 'Dos pueblos están a 4 cm en el mapa. ¿Cuál es la distancia real?', '[{"label":"A","text":"2 km.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. 4 × 50.000 = 200.000 cm = 2.000 m = 2 km."},{"label":"B","text":"20 km.","is_correct":false,"distractor_type":"Convierte mal las unidades.","explanation_feedback":"Incorrecta. 100.000 cm son 1 km."},{"label":"C","text":"12.500 cm.","is_correct":false,"distractor_type":"Divide en lugar de multiplicar.","explanation_feedback":"Incorrecta. Cada cm del mapa son 50.000 cm reales."},{"label":"D","text":"200 km.","is_correct":false,"distractor_type":"Convierte mal las unidades.","explanation_feedback":"Incorrecta. 200.000 cm son 2 km."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
