select 'afea1817-c8ea-57e4-b9b9-8dfeb0d28565', e.id, 'MA', (select id from public.content_components where code = 'MA.CAT.ALG'), 'qa_passed', 'continuous', '{"title":"Boletas para el festival","text":"Para un festival escolar, las boletas de niño cuestan $5.000 y las de adulto $8.000. Una familia compró 20 boletas y pagó $130.000.","svg":null,"table":null}'::jsonb, 'Si n es el número de boletas de niño y a el de adulto, ¿qué sistema representa la situación?', '[{"label":"A","text":"n + a = 130.000 y 5.000n + 8.000a = 20","is_correct":false,"distractor_type":"Intercambia los totales.","explanation_feedback":"Incorrecta. 20 es el número de boletas y 130.000 el dinero."},{"label":"B","text":"5.000n = 8.000a y n = a + 20","is_correct":false,"distractor_type":"Iguala los gastos sin razón.","explanation_feedback":"Incorrecta. El texto no dice que gasten lo mismo en cada tipo."},{"label":"C","text":"n + a = 20 y 5.000n + 8.000a = 130.000","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Una ecuación para el número de boletas y otra para el dinero."},{"label":"D","text":"n − a = 20 y 5.000n − 8.000a = 130.000","is_correct":false,"distractor_type":"Usa restas en lugar de sumas.","explanation_feedback":"Incorrecta. Las boletas y los gastos se suman."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
