select 'ecc2f9b3-7af8-58ac-9777-e742a20a7e01', e.id, 'MA', (select id from public.content_components where code = 'MA.CAT.ALG'), 'qa_passed', 'continuous', '{"title":"Boletas para el festival","text":"Para un festival escolar, las boletas de niño cuestan $5.000 y las de adulto $8.000. Una familia compró 20 boletas y pagó $130.000.","svg":null,"table":null}'::jsonb, '¿Cuántas boletas de adulto compró la familia?', '[{"label":"A","text":"16.","is_correct":false,"distractor_type":"Divide 130.000 entre 8.000 y redondea.","explanation_feedback":"Incorrecta. Ignora que también hay boletas de niño."},{"label":"B","text":"6.","is_correct":false,"distractor_type":"Resuelve mal el sistema.","explanation_feedback":"Incorrecta. Con 6 adultos y 14 niños se pagarían $118.000."},{"label":"C","text":"10.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. 5.000n + 8.000(20 − n) = 130.000 da n = 10, así que a = 10."},{"label":"D","text":"20.","is_correct":false,"distractor_type":"Supone que todas son de adulto.","explanation_feedback":"Incorrecta. 20 boletas de adulto costarían $160.000."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
